package org.mixxx;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

// Autonomously generated by an AI agent.
// Host test for the USB output change flags, including 20 unplug and replug cycles.
// End of comment autonomously generated by an AI agent.
public final class HardwareChangesTest {
    private static void check(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }

    private static Set<Integer> set(Integer... ids) {
        return new HashSet<>(Arrays.asList(ids));
    }

    public static void main(String[] args) {
        int audio = HardwareChanges.AUDIO;
        int lost = HardwareChanges.ROUTE_LOST;

        check(HardwareChanges.audioOutputs(set(), set()) == 0, "No outputs before or after is no change");
        check(HardwareChanges.audioOutputs(set(7), set(7)) == 0, "Same output set is no change");
        check(HardwareChanges.audioOutputs(set(), set(7)) == audio, "Plugging in only reports audio");
        check(HardwareChanges.audioOutputs(set(7), set()) == (audio | lost),
                "Unplugging must also report route loss");
        check(HardwareChanges.audioOutputs(set(7), set(9)) == (audio | lost),
                "Replacing the output is a removal and must stop playback");
        check(HardwareChanges.audioOutputs(set(7), set(7, 9)) == audio,
                "Adding a second output without removal must not stop playback");

        for (int cycle = 1; cycle <= 20; cycle++) {
            int id = 100 + cycle;
            check(HardwareChanges.audioOutputs(set(id), set()) == (audio | lost),
                    "Cycle " + cycle + ": unplug must stop playback");
            check(HardwareChanges.audioOutputs(set(), set(id)) == audio,
                    "Cycle " + cycle + ": replug must only request recovery");
        }

        check(HardwareChanges.MIDI == 2 && HardwareChanges.ROUTE_LOST == 4 && HardwareChanges.OUTPUT_FAILED == 8,
                "Flag values must match androidaudiofocus.cpp");
    }
}
